import pytest

from operations import add, subtract, divide


def test_add():
    assert add(2, 3) == 5


def test_subtract():
    assert subtract(5, 2) == 3


def test_divide():
    assert divide(5, 2) == 2.5


def test_divide_by_zero_raises_ValueError():
    with pytest.raises(ValueError):
        divide(1, 0)
